CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE slot_reservations (
 id UUID PRIMARY KEY, court_id UUID NOT NULL, facility_id UUID NOT NULL, holder_id UUID NOT NULL,
 starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL,
 state VARCHAR(20) NOT NULL CHECK(state IN ('HOLD','BOOKED','RELEASED')),
 quote JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 CHECK(starts_at<ends_at),
 EXCLUDE USING gist(court_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(state IN ('HOLD','BOOKED'))
);
CREATE INDEX idx_hold_expiry ON slot_reservations(expires_at) WHERE state='HOLD';
CREATE TABLE bookings (
 id UUID PRIMARY KEY, reservation_id UUID NOT NULL UNIQUE REFERENCES slot_reservations(id),
 facility_id UUID NOT NULL, court_id UUID NOT NULL, created_by UUID NOT NULL, customer_id UUID NOT NULL,
 current_holder_id UUID NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL,
 status VARCHAR(30) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','EXPIRED')),
 source VARCHAR(30) NOT NULL CHECK(source IN ('ONLINE','OFFLINE_COUNTER')),
 guest_name VARCHAR(180),guest_phone VARCHAR(30),amount NUMERIC(12,2) NOT NULL CHECK(amount>0),currency VARCHAR(3) NOT NULL,
 price_snapshot JSONB NOT NULL, hold_expires_at TIMESTAMPTZ NOT NULL,payment_id UUID,paid_at TIMESTAMPTZ,
 checkin_token_hash VARCHAR(64),checkin_token_version INT NOT NULL DEFAULT 0,
 checked_in_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(starts_at<ends_at)
);
CREATE INDEX idx_booking_customer ON bookings(current_holder_id,starts_at DESC);
CREATE INDEX idx_booking_facility ON bookings(facility_id,starts_at);
CREATE TABLE booking_history(id UUID PRIMARY KEY,booking_id UUID NOT NULL REFERENCES bookings(id),actor_id UUID,
 action VARCHAR(60) NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE request_idempotency(actor_id UUID NOT NULL,operation VARCHAR(50) NOT NULL,key VARCHAR(100) NOT NULL,
 fingerprint VARCHAR(64) NOT NULL,resource_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(actor_id,operation,key));
CREATE TABLE event_inbox(consumer VARCHAR(80) NOT NULL,event_id UUID NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(consumer,event_id));
CREATE TABLE event_outbox(event_id UUID PRIMARY KEY,exchange VARCHAR(120) NOT NULL,routing_key VARCHAR(120) NOT NULL,
 body JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,published_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE payment_reconciliation(id UUID PRIMARY KEY,booking_id UUID NOT NULL REFERENCES bookings(id),payment_id UUID NOT NULL UNIQUE,
 reason VARCHAR(120) NOT NULL,state VARCHAR(40) NOT NULL DEFAULT 'REQUIRES_REVIEW',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
-- Price snapshot may never be changed after creation, including transfers.
CREATE FUNCTION protect_booking_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.price_snapshot IS DISTINCT FROM OLD.price_snapshot OR NEW.amount<>OLD.amount OR NEW.currency<>OLD.currency
 THEN RAISE EXCEPTION 'Booking price snapshot is immutable'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER booking_snapshot_immutable BEFORE UPDATE ON bookings FOR EACH ROW EXECUTE FUNCTION protect_booking_snapshot();

CREATE TABLE booking_groups (
 id UUID PRIMARY KEY REFERENCES bookings(id), owner_id UUID NOT NULL, name VARCHAR(180) NOT NULL,
 state VARCHAR(30) NOT NULL CHECK(state IN ('GROUP_PENDING','CONFIRMED','GROUP_EXPIRED','GROUP_CANCELLED')),
 deadline TIMESTAMPTZ NOT NULL, max_members INT NOT NULL CHECK(max_members BETWEEN 1 AND 50),
 allocations_locked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE group_members (
 id UUID PRIMARY KEY, group_id UUID NOT NULL REFERENCES booking_groups(id), user_id UUID NOT NULL,
 display_name VARCHAR(180) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE,
 amount_due NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(amount_due>=0 AND amount_due=TRUNC(amount_due)),
 amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(amount_paid>=0 AND amount_paid<=amount_due),
 payment_state VARCHAR(40) NOT NULL DEFAULT 'UNPAID' CHECK(payment_state IN ('UNPAID','WAITING_FOR_PAYMENT','PAID','PAID_BY_OWNER')),
 payment_requested_at TIMESTAMPTZ, joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(group_id,user_id)
);
CREATE TABLE group_contributions (
 payment_id UUID PRIMARY KEY, group_id UUID NOT NULL REFERENCES booking_groups(id),
 member_id UUID NOT NULL REFERENCES group_members(id), payer_id UUID NOT NULL,
 amount NUMERIC(12,2) NOT NULL CHECK(amount>0), paid_at TIMESTAMPTZ NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_group_members_user ON group_members(user_id,group_id) WHERE active;

CREATE TABLE transfer_leases (
 listing_id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES bookings(id),seller_id UUID NOT NULL,
 price NUMERIC(12,2) NOT NULL CHECK(price>0),deadline TIMESTAMPTZ NOT NULL,
 state VARCHAR(20) NOT NULL CHECK(state IN ('ACTIVE','LOCKED','COMPLETED','RELEASED')),
 acquisition_id UUID,buyer_id UUID,expires_at TIMESTAMPTZ,payment_id UUID UNIQUE,
 updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX one_live_transfer_per_booking ON transfer_leases(booking_id) WHERE state IN ('ACTIVE','LOCKED');
CREATE TABLE transfer_lease_audit(id UUID PRIMARY KEY,listing_id UUID NOT NULL REFERENCES transfer_leases(listing_id),
 action VARCHAR(40) NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

-- Acceptance timestamp belongs to the obligation; events/history use the existing stores.
-- Legacy members have never been reminded. No payment/allocation state changes.
ALTER TABLE group_members ADD COLUMN last_reminder_at TIMESTAMPTZ;

CREATE TABLE sport_categories (
 id UUID PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE facilities (
 id UUID PRIMARY KEY, owner_id UUID NOT NULL, name VARCHAR(180) NOT NULL, phone VARCHAR(30) NOT NULL,
 address_line VARCHAR(500) NOT NULL, province VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL,
 ward VARCHAR(100) NOT NULL, description TEXT, timezone VARCHAR(80) NOT NULL,
 latitude NUMERIC(10,7), longitude NUMERIC(10,7), status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), version BIGINT NOT NULL DEFAULT 0,
 CHECK(status IN('DRAFT','PENDING_APPROVAL','ACTIVE','SUSPENDED','REJECTED'))
);
CREATE INDEX idx_facility_owner ON facilities(owner_id);
CREATE TABLE facility_amenities (facility_id UUID NOT NULL REFERENCES facilities(id), name VARCHAR(100) NOT NULL,
 PRIMARY KEY(facility_id,name));
CREATE TABLE courts (
 id UUID PRIMARY KEY, facility_id UUID NOT NULL REFERENCES facilities(id), sport_category_id UUID NOT NULL REFERENCES sport_categories(id),
 code VARCHAR(50) NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, enabled BOOLEAN NOT NULL DEFAULT TRUE,
 version BIGINT NOT NULL DEFAULT 0, UNIQUE(facility_id,code), UNIQUE(facility_id,name)
);
CREATE TABLE maintenance_windows (
 id UUID PRIMARY KEY, court_id UUID NOT NULL REFERENCES courts(id), starts_at TIMESTAMPTZ NOT NULL,
 ends_at TIMESTAMPTZ NOT NULL, reason VARCHAR(1200) NOT NULL, created_by UUID NOT NULL, cancelled BOOLEAN NOT NULL DEFAULT FALSE,
 CHECK(starts_at<ends_at)
);
CREATE INDEX idx_maintenance_court ON maintenance_windows(court_id,starts_at,ends_at);
CREATE TABLE facility_images (
 id UUID PRIMARY KEY, facility_id UUID NOT NULL REFERENCES facilities(id), court_id UUID REFERENCES courts(id),
 object_key VARCHAR(700) NOT NULL UNIQUE, content_type VARCHAR(80) NOT NULL, size_bytes BIGINT NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE facility_audit (
 id UUID PRIMARY KEY, actor_id UUID NOT NULL, facility_id UUID NOT NULL REFERENCES facilities(id),
 action VARCHAR(100) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), details TEXT
);

CREATE TABLE media_cleanup (
 object_key VARCHAR(500) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,
 next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE facility_transfer_policies (
 facility_id UUID PRIMARY KEY REFERENCES facilities(id),enabled BOOLEAN NOT NULL,
 min_lead_seconds INT NOT NULL CHECK(min_lead_seconds>=0 AND min_lead_seconds<=7776000),
 updated_by UUID NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE facility_reviews (
 id UUID PRIMARY KEY,facility_id UUID NOT NULL REFERENCES facilities(id),owner_id UUID NOT NULL,
 state VARCHAR(30) NOT NULL DEFAULT 'PENDING_APPROVAL',snapshot JSONB NOT NULL,
 submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),reviewed_at TIMESTAMPTZ,reviewed_by UUID,reason VARCHAR(2000),
 CHECK(state IN('PENDING_APPROVAL','APPROVED','REJECTED','SUPPLEMENT_REQUIRED'))
);
CREATE UNIQUE INDEX idx_pending_facility_review ON facility_reviews(facility_id) WHERE state='PENDING_APPROVAL';
CREATE TABLE facility_documents (
 id UUID PRIMARY KEY,facility_id UUID NOT NULL REFERENCES facilities(id),name VARCHAR(180) NOT NULL,
 object_key VARCHAR(700) NOT NULL UNIQUE,content_type VARCHAR(80) NOT NULL,size_bytes BIGINT NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE event_outbox(event_id UUID PRIMARY KEY,exchange VARCHAR(120) NOT NULL,routing_key VARCHAR(120) NOT NULL,
 body JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,published_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE FUNCTION protect_facility_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Facility audit is append-only'; END $$;
CREATE TRIGGER facility_audit_immutable BEFORE UPDATE OR DELETE ON facility_audit FOR EACH ROW EXECUTE FUNCTION protect_facility_audit();
CREATE FUNCTION protect_facility_review_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.owner_id<>OLD.owner_id OR NEW.facility_id<>OLD.facility_id
 THEN RAISE EXCEPTION 'Submitted facility snapshot is immutable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER facility_review_snapshot_immutable BEFORE UPDATE ON facility_reviews FOR EACH ROW EXECUTE FUNCTION protect_facility_review_snapshot();

ALTER TABLE facility_documents ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- A submitted review keeps its attachments for later inspection, even after a supplement replaces them.
CREATE INDEX idx_current_facility_documents ON facility_documents(facility_id) WHERE NOT archived;

CREATE TABLE first_facility_applications (
 application_id UUID PRIMARY KEY, facility_id UUID NOT NULL UNIQUE REFERENCES facilities(id),
 owner_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- UC-2.1 contact information, independent of the Owner's account credential.
-- Existing rows and immutable review snapshots remain unchanged.
ALTER TABLE facilities ADD COLUMN contact_email VARCHAR(254);

-- Phase 2A: move authoritative role/profile state out of users and harden
-- verification/refresh persistence without rewriting the committed V1 history.

CREATE TABLE user_roles (
    user_id     UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role        VARCHAR(20) NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, role),
    CONSTRAINT chk_user_roles_role CHECK (role IN ('CUSTOMER', 'OWNER', 'STAFF', 'ADMIN'))
);

-- Preserve existing development accounts. New registrations are created with
-- no row here; successful verification grants CUSTOMER.
INSERT INTO user_roles (user_id, role)
SELECT id, role
FROM users
WHERE status = 'ACTIVE' OR email_verified = TRUE OR phone_verified = TRUE;

DROP INDEX IF EXISTS idx_users_role;
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_role;
ALTER TABLE users DROP COLUMN role;

CREATE TABLE user_profiles (
    user_id        UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    full_name      VARCHAR(255) NOT NULL,
    avatar_url     VARCHAR(2048),
    date_of_birth  DATE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    version        BIGINT      NOT NULL DEFAULT 0
);

INSERT INTO user_profiles (user_id, full_name, avatar_url, created_at, updated_at, version)
SELECT id, full_name, avatar_url, created_at, updated_at, version FROM users;

ALTER TABLE users DROP COLUMN full_name;
ALTER TABLE users DROP COLUMN avatar_url;
ALTER TABLE users ADD COLUMN pending_email VARCHAR(255);
ALTER TABLE users ADD COLUMN pending_phone VARCHAR(20);
CREATE UNIQUE INDEX uq_users_pending_email ON users (LOWER(pending_email)) WHERE pending_email IS NOT NULL;
CREATE UNIQUE INDEX uq_users_email_lower ON users (LOWER(email));
CREATE UNIQUE INDEX uq_users_pending_phone ON users (pending_phone) WHERE pending_phone IS NOT NULL;

ALTER TABLE users ALTER COLUMN status SET DEFAULT 'PENDING_VERIFICATION';
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_status;
ALTER TABLE users ADD CONSTRAINT chk_users_status
    CHECK (status IN ('PENDING_VERIFICATION', 'ACTIVE', 'SUSPENDED', 'LOCKED', 'DEACTIVATED'));

-- Existing one-time values are invalidated before the column becomes a hash store.
ALTER TABLE otp_codes RENAME COLUMN code TO code_hash;
ALTER TABLE otp_codes ALTER COLUMN code_hash TYPE VARCHAR(255);
ALTER TABLE otp_codes ADD COLUMN token_hash VARCHAR(64);
UPDATE otp_codes
SET code_hash = 'invalidated:' || id::text,
    verified = TRUE
WHERE TRUE;
ALTER TABLE otp_codes ADD COLUMN verified_at TIMESTAMPTZ;
ALTER TABLE otp_codes DROP CONSTRAINT IF EXISTS chk_otp_purpose;
ALTER TABLE otp_codes ADD CONSTRAINT chk_otp_purpose
    CHECK (purpose IN ('EMAIL_VERIFY', 'EMAIL_CHANGE', 'PHONE_CHANGE', 'PASSWORD_RESET'));
CREATE INDEX idx_otp_codes_lookup ON otp_codes(user_id, purpose, verified, expires_at);

ALTER TABLE refresh_tokens ADD COLUMN rotated_from_id UUID REFERENCES refresh_tokens(id);
ALTER TABLE refresh_tokens ADD COLUMN last_used_at TIMESTAMPTZ;
CREATE INDEX idx_refresh_tokens_active ON refresh_tokens(user_id, revoked, expires_at);

ALTER TABLE users ALTER COLUMN email DROP NOT NULL;
ALTER TABLE users ADD CONSTRAINT chk_user_contact CHECK (email IS NOT NULL OR phone IS NOT NULL);
ALTER TABLE otp_codes ADD COLUMN recipient VARCHAR(255);
ALTER TABLE otp_codes DROP CONSTRAINT chk_otp_purpose;
ALTER TABLE otp_codes ADD CONSTRAINT chk_otp_purpose
 CHECK (purpose IN ('EMAIL_VERIFY','PHONE_VERIFY','EMAIL_CHANGE','PHONE_CHANGE','PASSWORD_RESET'));
ALTER TABLE staff_permissions ALTER COLUMN permission TYPE VARCHAR(64);

ALTER TABLE users ADD COLUMN locked_until TIMESTAMPTZ;
CREATE TABLE identity_notifications (
 id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),recipient VARCHAR(255) NOT NULL,
 subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'PENDING',
 attempts INT NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error VARCHAR(500),sent_at TIMESTAMPTZ,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE FUNCTION protect_identity_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Identity audit records are append-only'; END $$;
CREATE TRIGGER identity_audit_immutable BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION protect_identity_audit();

CREATE TABLE event_inbox(consumer VARCHAR(80) NOT NULL,event_id UUID NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(consumer,event_id));
ALTER TABLE identity_notifications ADD COLUMN source_key VARCHAR(180);
CREATE UNIQUE INDEX idx_identity_notice_source ON identity_notifications(source_key) WHERE source_key IS NOT NULL;

CREATE TABLE owner_applications (
 id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), facility_id UUID NOT NULL UNIQUE,
 state VARCHAR(30) NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','SUBMITTING','PENDING_APPROVAL','SUPPLEMENT_REQUIRED','DECIDING','APPROVING','APPROVED','REJECTED')),
 business_name VARCHAR(180) NOT NULL, facility_name VARCHAR(180) NOT NULL,
 private_payload TEXT NOT NULL, initial_facility JSONB NOT NULL,
 submitted_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, reviewed_by UUID REFERENCES users(id),
 reason VARCHAR(1200), decision_action VARCHAR(30), submission_origin VARCHAR(30), commission_percent NUMERIC(5,2) CHECK(commission_percent BETWEEN 0 AND 100),
 next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), lease_until TIMESTAMPTZ,
 lease_token UUID, last_error VARCHAR(300), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX owner_one_open_application ON owner_applications(user_id) WHERE state <> 'REJECTED';
CREATE INDEX owner_application_review_queue ON owner_applications(state,submitted_at);
CREATE TABLE owner_application_submissions (
 id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES owner_applications(id),
 private_snapshot TEXT NOT NULL, facility_snapshot JSONB NOT NULL,
 submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TRIGGER owner_submission_immutable BEFORE UPDATE OR DELETE ON owner_application_submissions
 FOR EACH ROW EXECUTE FUNCTION protect_identity_audit();

CREATE TABLE payment_orders (
 id UUID PRIMARY KEY,booking_id UUID NOT NULL,payer_id UUID NOT NULL,member_id UUID,purpose VARCHAR(30) NOT NULL,
 amount NUMERIC(12,2) NOT NULL CHECK(amount>0),currency VARCHAR(3) NOT NULL,
 provider VARCHAR(40) NOT NULL,provider_reference VARCHAR(120) NOT NULL UNIQUE,
 status VARCHAR(30) NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED','EXPIRED')),
 idempotency_key VARCHAR(100) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,paid_at TIMESTAMPTZ,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 UNIQUE(payer_id,idempotency_key)
);
CREATE UNIQUE INDEX uq_pending_payment ON payment_orders(booking_id,payer_id,purpose,COALESCE(member_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE status='PENDING';
CREATE TABLE provider_callbacks(provider VARCHAR(40) NOT NULL,transaction_id VARCHAR(120) NOT NULL,
 payment_id UUID NOT NULL REFERENCES payment_orders(id),fingerprint VARCHAR(64) NOT NULL,body JSONB NOT NULL,
 received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(provider,transaction_id));
CREATE TABLE payment_audit(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payment_orders(id),actor_id UUID,
 action VARCHAR(80) NOT NULL,details JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE event_outbox(event_id UUID PRIMARY KEY,exchange VARCHAR(120) NOT NULL,routing_key VARCHAR(120) NOT NULL,
 body JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,published_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE refunds(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payment_orders(id),requester_id UUID NOT NULL,
 reason VARCHAR(500) NOT NULL,state VARCHAR(40) NOT NULL,amount NUMERIC(12,2),policy_reference VARCHAR(120),
 idempotency_key VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(requester_id,idempotency_key));

-- Every accepted create key must keep its result even after the payment becomes final.
CREATE TABLE payment_requests (
 payer_id UUID NOT NULL, idempotency_key VARCHAR(100) NOT NULL,
 booking_id UUID NOT NULL, member_id UUID, payment_id UUID NOT NULL REFERENCES payment_orders(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(payer_id,idempotency_key)
);
INSERT INTO payment_requests(payer_id,idempotency_key,booking_id,member_id,payment_id)
 SELECT payer_id,idempotency_key,booking_id,member_id,id FROM payment_orders;

CREATE TABLE event_inbox (
 consumer VARCHAR(80) NOT NULL,event_id UUID NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 PRIMARY KEY(consumer,event_id)
);

ALTER TABLE payment_orders ADD COLUMN acquisition_id UUID;
ALTER TABLE payment_orders ADD COLUMN seller_id UUID;
ALTER TABLE payment_requests ADD COLUMN acquisition_id UUID;
DROP INDEX uq_pending_payment;
CREATE UNIQUE INDEX uq_pending_payment ON payment_orders(booking_id,payer_id,purpose,
 COALESCE(member_id,'00000000-0000-0000-0000-000000000000'::uuid),COALESCE(acquisition_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE status='PENDING';
ALTER TABLE payment_orders ADD CONSTRAINT valid_transfer_reference CHECK((purpose='TRANSFER' AND acquisition_id IS NOT NULL AND seller_id IS NOT NULL AND member_id IS NULL) OR (purpose<>'TRANSFER' AND acquisition_id IS NULL));
CREATE TABLE transfer_escrow (
 payment_id UUID PRIMARY KEY REFERENCES payment_orders(id),acquisition_id UUID NOT NULL,payer_id UUID NOT NULL,seller_id UUID NOT NULL,
 amount NUMERIC(12,2) NOT NULL CHECK(amount>0),currency VARCHAR(3) NOT NULL,
 state VARCHAR(40) NOT NULL CHECK(state IN ('HELD_POLICY_BLOCKED','REFUND_REVIEW')),
 policy_reference VARCHAR(120) NOT NULL DEFAULT 'BLOCKED_RULE:ESCROW_RELEASE',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Preserve the initial migration and remove its one-interval restriction.
ALTER TABLE operating_hours DROP CONSTRAINT uq_operating_hours;
CREATE UNIQUE INDEX uq_operating_interval ON operating_hours
 (facility_id, COALESCE(court_id,'00000000-0000-0000-0000-000000000000'::uuid),day_of_week,open_time,close_time) WHERE is_active;
ALTER TABLE pricing_rules ADD COLUMN effective_from DATE NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE pricing_rules ADD COLUMN effective_to DATE;
ALTER TABLE pricing_rules ADD COLUMN currency VARCHAR(3) NOT NULL DEFAULT 'VND';
ALTER TABLE pricing_rules ADD COLUMN sport_category_id UUID;
ALTER TABLE pricing_rules ADD CONSTRAINT chk_effective_period CHECK(effective_to IS NULL OR effective_to >= effective_from);
-- Old zero-price rows cannot be used for quoting; retain them for history.
UPDATE pricing_rules SET is_active=FALSE WHERE price_per_slot=0;
ALTER TABLE pricing_rules ADD CONSTRAINT chk_positive_active_price CHECK(NOT is_active OR price_per_slot>0);
CREATE TABLE schedule_audit (
 id UUID PRIMARY KEY, facility_id UUID NOT NULL, actor_id UUID NOT NULL,
 action VARCHAR(80) NOT NULL, snapshot JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_schedule_audit ON schedule_audit(facility_id,created_at);

CREATE TABLE application_configuration_freeze (
 facility_id UUID PRIMARY KEY, application_id UUID NOT NULL UNIQUE, frozen BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE transfer_listings (
 id UUID PRIMARY KEY,booking_id UUID NOT NULL,seller_id UUID NOT NULL,facility_id UUID NOT NULL,court_id UUID NOT NULL,
 snapshot JSONB NOT NULL,original_amount NUMERIC(12,2) NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>0 AND price<=original_amount),currency VARCHAR(3) NOT NULL,
 starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,deadline TIMESTAMPTZ NOT NULL CHECK(deadline<=starts_at),
 state VARCHAR(30) NOT NULL CHECK(state IN ('ACTIVE','LOCKED','COMPLETED','WITHDRAWN','EXPIRED','PENDING_AUDIT')),
 workflow VARCHAR(30) NOT NULL CHECK(workflow IN ('REGISTER','READY','EDIT','LOCK','UNLOCK','WITHDRAW','HANDOFF','REVIEW')),
 active_acquisition_id UUID,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(500),
 version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX one_active_listing_per_booking ON transfer_listings(booking_id) WHERE state IN ('ACTIVE','LOCKED','PENDING_AUDIT');
CREATE TABLE transfer_acquisitions (
 id UUID PRIMARY KEY,listing_id UUID NOT NULL REFERENCES transfer_listings(id),buyer_id UUID NOT NULL,
 amount NUMERIC(12,2) NOT NULL CHECK(amount>0),currency VARCHAR(3) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,
 state VARCHAR(30) NOT NULL CHECK(state IN ('PENDING','PENDING_HANDOFF','SUCCESS','CANCELLED','EXPIRED','FAILED','PENDING_AUDIT')),
 payment_id UUID UNIQUE,payment_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE request_idempotency(actor_id UUID NOT NULL,operation VARCHAR(40) NOT NULL,key VARCHAR(100) NOT NULL,
 fingerprint VARCHAR(64) NOT NULL,resource_id UUID NOT NULL,PRIMARY KEY(actor_id,operation,key));
CREATE TABLE transfer_audit(id UUID PRIMARY KEY,listing_id UUID NOT NULL REFERENCES transfer_listings(id),actor_id UUID,
 action VARCHAR(60) NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE event_inbox(consumer VARCHAR(80) NOT NULL,event_id UUID NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(consumer,event_id));
CREATE TABLE event_outbox(event_id UUID PRIMARY KEY,exchange VARCHAR(120) NOT NULL,routing_key VARCHAR(120) NOT NULL,
 body JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,published_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE transfer_reconciliation(id UUID PRIMARY KEY,listing_id UUID NOT NULL REFERENCES transfer_listings(id),payment_id UUID NOT NULL UNIQUE,
 payer_id UUID NOT NULL,reason VARCHAR(120) NOT NULL,state VARCHAR(40) NOT NULL DEFAULT 'REQUIRES_REVIEW',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
